#include <Snooker/Service/PocketSimulation.h>
#include <Snooker/Shot/ShotInput.h>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <iostream>
namespace fs=std::filesystem;
std::string Read(const char*p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("cannot read package input");return {std::istreambuf_iterator<char>(f),{}};}void Write(const fs::path&p,const std::string&t){std::ofstream f(p,std::ios::binary);if(!f||!(f<<t))throw std::runtime_error("cannot write package file");}
int main(int argc,char**argv){using namespace Snooker;try{if(argc!=4)throw std::runtime_error("usage: snooker_fault_package fault.txt shot.input output-directory");const auto faultText=Read(argv[1]),inputText=Read(argv[2]);PhysicsFault fault;ShotInput input;PocketSimulationConfig config;std::string error;if(!PhysicsFault::Deserialize(faultText,fault,&error)||fault.ReplayConfig.empty()||!PocketSimulationConfig::Deserialize(fault.ReplayConfig,config,&error)||!ShotInput::Deserialize(inputText,input,&error))throw std::runtime_error(error);const fs::path out=argv[3];if(fs::exists(out)&&!fs::is_empty(out))throw std::runtime_error("fault package output must be empty");fs::create_directories(out);Write(out/"fault.txt",faultText);Write(out/"checkpoint.snapshot",fault.Snapshot.Serialize());Write(out/"physics.bundle",fault.ReplayConfig);Write(out/"shot.input",input.Serialize());Write(out/"fault.log","code="+std::string(PhysicsFaultCodeName(fault.Code))+"\nstep="+std::to_string(fault.Step)+"\ntime="+std::to_string(fault.Time)+"\nball="+std::to_string(fault.Ball)+"\nmessage="+fault.Message+"\n");Write(out/"README.txt","Fault package v1\nRun: snooker_fault_replay fault.txt\nThe checkpoint and embedded bundle are the replay inputs. shot.input is retained for shot-level diagnosis.\n");Write(out/"manifest.txt","snooker-fault-package-v1\nfault fault.txt\ncheckpoint checkpoint.snapshot\nbundle physics.bundle\ninput shot.input\nlog fault.log\nreadme README.txt\n");std::cout<<"PASS fault package "<<out.string()<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
